    mkdir -p "$(dirname "$plist_dest")"

    cat > "$plist_dest" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key><string>${plist_label}</string>
    <key>ProgramArguments</key>
    <array>
        <string>/usr/bin/env</string>
        <string>python3</string>
        <string>${OPENCLAW_HOME}/scripts/tnode_config_sync.py</string>
    </array>
    <key>EnvironmentVariables</key>
    <dict>
        <key>PATH</key><string>/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin</string>
        <key>HOME</key><string>${HOME}</string>
        <key>OPENCLAW_HOME</key><string>${OPENCLAW_HOME}</string>
        <key>TNODE_CONFIG_SYNC_ONESHOT</key><string>1</string>
    </dict>
    <key>WatchPaths</key>
    <array>
        <string>${OPENCLAW_HOME}/openclaw.json</string>
    </array>
    <key>ThrottleInterval</key><integer>5</integer>
    <key>StandardOutPath</key><string>${OPENCLAW_HOME}/logs/tnode-config-sync-watch.out.log</string>
    <key>StandardErrorPath</key><string>${OPENCLAW_HOME}/logs/tnode-config-sync-watch.err.log</string>
</dict>
</plist>
PLIST

    launchctl unload "$plist_dest" 2>/dev/null || true
    launchctl load "$plist_dest"
    success "LaunchAgent tnode-config-sync-watch cargado"
}

install_config_sync_systemd() {
    if ! command_exists systemctl; then
        warn "systemctl no disponible — saltando systemd setup del config-sync"
        return 0
    fi
    _systemd_update_only_handled "tnode-config-sync" && return 0

    local systemd_dir="/etc/systemd/system"

    cat > "$systemd_dir/tnode-config-sync.service" <<SVCUNIT
[Unit]
Description=TNode config-sync — command executor + openclaw.json mirror
After=network-online.target
Wants=network-online.target
StartLimitIntervalSec=0

[Service]
Type=simple
User=${TNODE_USER}
ExecStart=/usr/bin/env python3 ${OPENCLAW_HOME}/scripts/tnode_config_sync.py
Restart=always
RestartSec=10
Environment=PATH=/usr/local/bin:/usr/bin:/bin
Environment=HOME=${TNODE_HOME}
Environment=OPENCLAW_HOME=${OPENCLAW_HOME}
EnvironmentFile=-%h/.config/tnode/env
StandardOutput=append:${OPENCLAW_HOME}/logs/tnode-config-sync.out.log
StandardError=append:${OPENCLAW_HOME}/logs/tnode-config-sync.err.log

[Install]
WantedBy=multi-user.target
SVCUNIT

    systemctl daemon-reload
    systemctl enable --now tnode-config-sync.service 2>/dev/null || true
    success "systemd tnode-config-sync habilitado (User=$TNODE_USER)"
}

install_config_sync_systemd_watcher() {
    if ! command_exists systemctl; then
        return 0
    fi
    _systemd_update_only_handled "tnode-config-sync-watch" && return 0

    local systemd_dir="/etc/systemd/system"

    cat > "$systemd_dir/tnode-config-sync-watch.service" <<SVCUNIT
[Unit]
Description=TNode config-sync — push openclaw.json change (oneshot)

[Service]
Type=oneshot
User=${TNODE_USER}
Environment=PATH=/usr/local/bin:/usr/bin:/bin
Environment=HOME=${TNODE_HOME}
Environment=OPENCLAW_HOME=${OPENCLAW_HOME}
Environment=TNODE_CONFIG_SYNC_ONESHOT=1
ExecStart=/usr/bin/env python3 ${OPENCLAW_HOME}/scripts/tnode_config_sync.py
EnvironmentFile=-%h/.config/tnode/env
StandardOutput=append:${OPENCLAW_HOME}/logs/tnode-config-sync-watch.out.log
StandardError=append:${OPENCLAW_HOME}/logs/tnode-config-sync-watch.err.log
SVCUNIT

    cat > "$systemd_dir/tnode-config-sync-watch.path" <<PATHU
[Unit]
Description=Watch openclaw.json and trigger tnode-config-sync-watch.service

[Path]
PathChanged=${OPENCLAW_HOME}/openclaw.json
Unit=tnode-config-sync-watch.service

[Install]
WantedBy=multi-user.target
PATHU

    systemctl daemon-reload
    systemctl enable --now tnode-config-sync-watch.path 2>/dev/null || true
    success "systemd tnode-config-sync-watch.path habilitado"
}

install_config_sync_wake_systemd() {
    if ! command_exists systemctl; then
        return 0
    fi
    _systemd_update_only_handled "tnode-config-sync-wake" && return 0

    local systemd_dir="/etc/systemd/system"

    cat > "$systemd_dir/tnode-config-sync-wake.service" <<SVCUNIT
[Unit]
Description=TNode config-sync — drain command queue once (wake)

[Service]
Type=oneshot
User=${TNODE_USER}
Environment=PATH=/usr/local/bin:/usr/bin:/bin
Environment=HOME=${TNODE_HOME}
Environment=OPENCLAW_HOME=${OPENCLAW_HOME}
Environment=TNODE_CONFIG_SYNC_DRAIN=1
ExecStart=/usr/bin/env python3 ${OPENCLAW_HOME}/scripts/tnode_config_sync.py
EnvironmentFile=-%h/.config/tnode/env
StandardOutput=append:${OPENCLAW_HOME}/logs/tnode-config-sync-wake.out.log
StandardError=append:${OPENCLAW_HOME}/logs/tnode-config-sync-wake.err.log
SVCUNIT

    cat > "$systemd_dir/tnode-config-sync-wake.path" <<PATHU
[Unit]
Description=Watch .wake and drain the command queue once (Dashboard→Chat wake)

[Path]
PathModified=${OPENCLAW_HOME}/.wake
Unit=tnode-config-sync-wake.service

[Install]
WantedBy=multi-user.target
PATHU

    systemctl daemon-reload
    systemctl enable --now tnode-config-sync-wake.path 2>/dev/null || true
    success "systemd tnode-config-sync-wake.path habilitado"
}

# ─────────────────────────────────────────────────────────────
# tnode-chat-sync: mirrors OpenClaw session turns to Firestore
# so chat history survives app close / device switches. Runs
# regardless of which LLM provider powers the node.
#
# The Python daemon is embedded verbatim from the canonical
# cmoralestbrain/skills/tnode-chat-sync/scripts/tnode_chat_sync.py
# (repo is private — we can't curl it). Keep in sync via the
# tnode-chat-sync tag published in that repo.
# ─────────────────────────────────────────────────────────────

write_tnode_chat_sync_py() {
    local dest="$1"
    cat > "$dest" <<'CHATSYNCPYEOF'
#!/usr/bin/env python3
"""tnode-chat-sync — mirrors OpenClaw session turns to Firestore.

Why: the TNode mobile app talks to its OpenClaw agent over a raw WebSocket.
If the user closes the app while the agent is still responding, that turn
is lost because it never hit disk in a place the app can fetch later.

This watcher tails the JSONL session files under
  ~/.openclaw/agents/<agent_id>/sessions/*.jsonl
and, for every new turn (a message line with role=user|assistant),
writes it to Firestore at
  users/{uid}/nodes/{nodeId}/chats/{messageId}
using a Firebase custom token minted by the `mintNodeToken` Cloud Function.

Authentication:
- Config at ~/.openclaw/tnode-chat-sync.json is created by tnode-setup.sh
  post-pairing with {nodeId, nodeSecret, mintUrl}.
- For each token mint cycle: sign HMAC(nodeSecret, f"{nodeId}:{ts}:{nonce}"),
  POST to mintUrl, receive Firebase customToken, exchange at
  identitytoolkit for an idToken valid ~1h.

Design notes:
- stdlib only (urllib, hmac, hashlib, json, time, os, pathlib).
- Dedup: Firestore doc id is deterministic:
    * user messages  -> u_<hash(content+ts)>  (or u_<idempotencyKey> if
      the line carries one; not usually present server-side)
    * assistant msgs -> a_<hash(content+ts)>
  This keeps the watcher idempotent on restart and avoids duplicating a
  message the Flutter client already wrote client-side.
- Polling cadence: 500ms. Low CPU, good-enough latency for chat UX.
- File tracking: (device, inode) -> byte offset. Handles rotation.

Chat outbox (v1.17.0+): the app writes user messages to chats/ with
delivery="pending"; when the direct WS path didn't deliver them, this
daemon injects them into the local gateway (ephemeral WS, chat.send with
the original idempotencyKey) and flips delivery="node". Firestore is the
guaranteed messaging path; the direct WS is just the low-latency one.

Shared-agent guests (v1.18.0+): other users can join this agent via an
invite link (see architecture_shared_agent_links.md). A guest chats from
their OWN space `users/<guestUid>/nodes/<nodeId>/chats` with a per-guest
sessionKey `tnode-guest-<guestUid>__<uuid>`. The outbox consumer adds a
collection-group sweep (nodeId==, delivery==pending, role==user) so a
single query covers every guest, validates each message's owner against
`nodeSyncRegistrations/<nodeId>/members/` (the authz source of truth), and
routes the assistant reply back to the guest's space by reading the uid
embedded in the sessionKey. The guest never pairs with the gateway.

Env/overrides:
  TNODE_CHAT_SYNC_CONFIG    Path to config JSON (default ~/.openclaw/tnode-chat-sync.json)
  TNODE_CHAT_SYNC_SESSIONS  Sessions dir (default ~/.openclaw/agents/<agent>/sessions)
  TNODE_CHAT_SYNC_LOG       Log file (default ~/.openclaw/logs/tnode-chat-sync.log)
  TNODE_CHAT_SYNC_POLL_MS   Polling interval ms (default 500)
  TNODE_CHAT_SYNC_OUTBOX_HOT_S / _OUTBOX_IDLE_S  Outbox poll cadence
  TNODE_CHAT_SYNC_GATEWAY_WS  Gateway WS url (default ws://127.0.0.1:18789)
  TNODE_CHAT_SYNC_DECL_THROTTLE_S  Min seconds between declarative-refresh spawns (default 5)
  TNODE_CHAT_SYNC_PRESENCE_FILE    App-presence touch file (default ~/.openclaw/app-presence)
  TNODE_CHAT_SYNC_PRESENCE_FRESH_S Presence freshness window (default 90)
  TNODE_CHAT_SYNC_UPLOAD_POLL_IDLE_S / _CRON_CMD_IDLE_S / _TASK_CMD_IDLE_S
                            Idle backstop cadences for uploads/commands (default 30)
  TNODE_CHAT_SYNC_CRON_MIRROR_IDLE_S / _TASKS_MIRROR_IDLE_S  Idle mirror scan (default 60)
  TNODE_CHAT_SYNC_MIRROR_RECONCILE_S  Mirror full-reconcile backstop (default 600)
"""
from __future__ import annotations
# 1.28.0 — Adaptive Firestore cadence (read-cost fix, auditoría 2026-07-04:
#          ~146k queries/día/nodo con la flota EN REPOSO). Los relojes rápidos
#          (uploads 2s, cron/task commands 3s, mirrors 10s, transport GET 10s)
#          solo corren así mientras el nodo está HOT: actividad reciente de
#          trajectory/outbox, o el app sosteniendo un WS a través del sidecar
#          de telemetría (archivo app-presence, tnode-telemetry 1.18.0+).
#          En idle: backstops de 30s (uploads/commands), 60s (mirror scans) y
#          90s (transport TTL). Los mirrors de crons/tasks además quedan
#          change-gated por hash del snapshot local + reconcile de 600s — un
#          nodo en reposo ya no re-lista ni re-escribe cada cron doc cada 10s.
#          El outbox conserva su idle de 10s: es el camino GARANTIZADO de
#          entrada para guests (Firestore-first, sin WS) y no debe degradarse.
# 1.26.0 — Fresh-node guest DELIVERY fix: the session tailer now re-resolves
#          `agents/*/sessions` on EVERY pass and ADDS new dirs, instead of only
#          re-resolving while the watched set was empty. On a snapshot-
#          provisioned node `agents/guest/sessions` is created only on the FIRST
#          guest turn — after the daemon started AND after `agents/main/sessions`
#          already appeared — so the one-shot resolution never watched it and the
#          guest's replies were never mirrored to Firestore (guest stuck on
#          "escribiendo" until a manual chat-sync restart). Additive + inode-keyed
#          offsets mean a dir is never dropped or re-read once seen. Pairs with
#          config-sync 1.28.0 (guest agent materializes through the boot race) to
#          make Opción B born-ready for guests on fresh nodes.
# 1.25.0 — Per-guest agent routing (Opción B): inject guest sessions under the
#          dedicated `guest` agent by prefixing the injected sessionKey with
#          `agent:guest:` (the gateway honors the prefix, verified E2E
#          2026-06-22) so guests never load the owner's main workspace
#          (USER.md/MEMORY.md/memory). The tailer now watches ALL
#          `agents/*/sessions` dirs (flush_turn already filters to
#          tnode-mobile/tnode-guest), so the guest agent's replies get mirrored
#          to each guest's own space.
# 1.23.0 — Declarative refresh trigger: when the session tailer sees a brand-new
#          live session, spawn tnode-config-sync DECL_ONESHOT to refresh the
#          workspace .md (throttled, fire-and-forget). Replaces config-sync's
#          Firestore poll → Document reads scale with sessions, not the clock.
# 1.30.0 — espejo de grupos WA DETECTADOS: al tailear turnos de sesiones
#          whatsapp:group:* se extraen conversation_label (JID) +
#          group_subject (nombre) del bloque "Conversation info" y se
#          upsertea channels/whatsapp.detectedGroups.{jid}={name,lastSeenAt}
#          (throttle 6h/nombre). Alimenta el picker de grupos por NOMBRE del
#          app (el usuario nunca ve JIDs). Ver architecture WA v1.5.
# 1.32.0 — AWMF P2 (lado nodo): entrega de Task Cards del motor awmf* —
#          poll wfInbox (status=pending, solo assignees agente), render
#          solo-protocolo con marca de origen §15.5 preservada, inyección en
#          sesión fresca `agent:<id>:awmf-<cardId>` vía chat.send, marker de
#          sesión para el plugin (identidad+perímetro+allowedTools §19.3.2)
#          y marker local de entregado (reentrega tras pérdida = conforme,
#          idempotente por cardRef+attempt).
# 1.33.0 — el render de la Task Card se reescribe para el modelo MÁS CHICO de
#          la flota (§18.3.3): PROTOCOLO de 3 pasos numerados en orden de
#          ejecución, una acción por paso y llamada de ejemplo literal a
#          awmf_result. Corrige los 3 defectos de contrato cazados en el 1er
#          ciclo real de la Mini (qwen3.5-9b, 2026-07-22): (1) abrir con
#          "responde ÚNICAMENTE con awmf_result" invertía el orden y el modelo
#          ejecutaba y se detenía sin reportar; (2) nadie pedía propagar el
#          runId a la herramienta de trabajo ⇒ artefactos huérfanos sin
#          `awmf.runId`; (3) los descriptores de evidencia no decían de DÓNDE
#          sale cada valor. La evidencia esperada se enumera UNA sola vez
#          (en el PASO 2) — antes salía dos veces con distinta redacción.
# 1.35.0 — TARJETA NATURAL (diseño 2026-08-04, con context-engine ≥0.22.0 y
#          engine ≥0.6.1): el modelo YA NO copia identificadores — el marker
#          de sesión gana attempt+stateVersion y las tools (awmf_result,
#          request_approval, guest_send) resuelven TODA la contabilidad de
#          ahí. El render se reescribe como orden de trabajo en lenguaje de
#          negocio: TU TAREA = stageName del Owner; sección CÓMO PUEDES
#          LOGRARLO generada desde card.sources (fuentes declaradas: leer
#          hojas con sus habilidades = libre; acciones con efectos = solo
#          allowedTools); data vacío se dice honesto ("failed vale, done
#          inventado no"). Muere el ejemplo de llamada formada en texto —
#          qwen (run wf-ba439617, 2026-08-04) lo contestó como texto plano
#          y el workItem quedó issued para siempre.
# 1.36.0: el render referencia el workspace-skill awmf — acuñar citas
#          (cita fila|ausencia) y pre-flight de evidencia (validar) antes
#          de awmf_result. El protocolo vive en la tarjeta; lo mecánico
#          se vuelve script (config-sync >=1.64.0 materializa el skill).
# 1.37.0 — FAIL-FAST de tarjetas huérfanas (incidente qwen 2026-08-08): una
#          tarjeta entregada cuyo turno murió sin awmf_result (timeout del
#          modelo, crash del gateway) quedaba esperando el lease de 1h del
#          motor. Ahora el sweep detecta el caso con las señales locales del
#          gateway (sin `.jsonl.lock` vivo = ningún turno corriendo;
#          awmf_result es síncrono dentro del turno ⇒ turno terminado +
#          tarjeta aún pending = resultado inexistente, sin carrera), borra
#          los markers (delivered + sesión) y re-entrega la MISMA emisión en
#          el mismo sweep — automatiza la receta manual del incidente.
#          Gracia de 90s post-entrega (ventana accept→lock) y tope de 2
#          fail-fasts por (cardId, attempt): a la 3ª muerte el problema no es
#          transitorio y se cede al lease del motor.
# 1.38.0 — FIX leak de espejo (2026-08-16, HEB β): el texto interno de una
#          Task Card AWMF de `recepcion` apareció en el chat del owner. El
#          jsonl LEGACY de la sesión se taileó (race de nacimiento vs el
#          shadow del trajectory), sus entries no traen sessionKey, y el
#          compat "sin sessionKey sigue fluyendo" (pensado para OpenClaw
#          ≤2026.4.x mono-agente) lo mandó al hilo del owner por default.
#          Fix: el tailer enhebra el agente dueño del archivo (srcAgent) en
#          cada turno y flush_turn NO espeja turnos sin sessionKey de
#          agentes ≠ main. Familia de [[chat_sync_delivery_mirror_leak]].
# 1.39.1 — cierra el lag de enforcement F5a (E2E 2026-08-27): el decl-refresh
#          event-driven solo disparaba con sesiones NUEVAS, así que un cliente
#          A2A repitiendo el mismo contextId no provocaba refresh y el
#          `exhausted` derivado por la CF tardaba hasta el backstop. Ahora
#          _a2a_sync_usage dispara _trigger_declarative_refresh tras subir
#          usage, con delay (~8s, TNODE_CHAT_SYNC_A2A_DECL_DELAY_S) para que
#          la CF recomponga a2aHash ANTES de que el oneshot lea el node doc.
# 1.40.0 — F5b transparencia del Medidor (pedido de tobal 2026-08-28): el
#          mini-tailer A2A captura también los TURNOS (user + assistant, solo
#          bloques text — nunca thinking) y los espeja como `recentTurns` en
#          a2aClients/{clientId}: array capped (30 turnos × 400 chars, con
#          ctx corto + ts) en el MISMO doc que ya lee la pantalla del Medidor
#          — cero rules/índices nuevos. PATCH combinado con usage (updateMask
#          múltiple) o solo-dialog; fingerprint aparte (dialogs_uploaded).
#          El sess_map ahora también matchea keys agent-prefijadas
#          (`agent:<id>:a2a-…`) y expone el contextId.
# 1.41.0 — F5c transparencia lado CONSUMIDOR (pedido de tobal): espejo de la
#          bitácora `a2a-peer-dialog.jsonl` que escribe el skill a2a-agent
#          1.1.0 en cada `call` a un contratado → `recentTurns` en
#          a2aPeers/{peerId} (mismo shape capped que el lado vendedor; role
#          user = NUESTRO agente, assistant = el tercero). El dueño ve desde
#          Equipo qué manda su agente a terceros y qué le contestan.
# 1.42.0 — F5d medidor del PROVEEDOR en el lado consumidor: el skill 1.2.0
#          captura el header x-a2a-usage (calls/costUsd/limits/status — el
#          server A2A 0.5.0 lo emite leyendo su propio colector) en la
#          bitácora; se espeja como `providerUsage` en a2aPeers/{peerId}
#          (fingerprint aparte, PATCH combinado con recentTurns) → la barra
#          de saldo disponible en el tile de Equipo.
# 1.43.0: F7c checkout — `_a2a_mirror_new_peers`: da de alta en Firestore
#          a2aPeers/ los contratados que el skill tnode-a2a registró al
#          canjear un claim (cola a2a-peer-mirror-queue.json, archivo aparte
#          para no compartir a2a-peers.json con config-sync) → el peer
#          aparece solo en Equipo y el enrich CF lo completa.
# 1.44.0: regla una-activa en el claim — la cola de espejo acepta entradas
#          op:"disable" (keys hermanas del mismo proveedor que el skill 2.2.0
#          desactivó al canjear): PATCH solo `enabled=false` en su doc.
# 1.45.0: fix consumo perdido con client ids LARGOS (device-check +240): el
#          gateway trunca el sessionKey (`paquete-animes-e4736-1b0fcb` →
#          `…-1b0` en sessions.json) → el PATCH de usage iba a un doc
#          inexistente y fallaba en silencio. El sess_map ahora resuelve el
#          id parseado contra los clients de la config del plugin (exacto o
#          prefijo ÚNICO, case-insensitive); cache invalidado también por
#          mtime de openclaw.json. Borrar a2a-usage-state.json = backfill.
# 1.46.0: paths del render AWMF actualizados a la estandarización tnode-*
#          (workspace/skills/awmf → tnode-awmf; par de config-sync 1.85.0).
# 1.47.0: OpenClaw 2.0 retira el default implicito a `main` en rosters
#          multi-agente — chat.send de keys crudas del owner ahora manda
#          `agentId: main` como PARAMETRO (la key canonica queda intacta;
#          prefijar la key SI la cambia en 2.0 y rompe espejo/eventos).
# 1.48.0: grupos WA detectados desde el store SQLite de OpenClaw 2.0
#          (`agents/*/agent/openclaw-agent.sqlite`, tabla `conversations`):
#          2.0 ya no escribe sesiones .jsonl ni el bloque "Conversation info",
#          así que el tail legacy no detectaba nada y el picker del app decía
#          "aún no se detectan grupos" mientras el agente contestaba en el
#          grupo. Nombre = `subject` de metadata_json si existe, si no el
#          slug del label des-slugificado. Mismo reloj que el mirror de tasks.
# 1.49.0: mirror de Tareas lee `task_runs` del state DB unificado de
#          OpenClaw 2.0+ (`state/openclaw.sqlite`). El legacy
#          `tasks/runs.sqlite` ya no existe en nodos 2.0/9.x (HEB β: dir
#          vacío desde 2026-09-02) y `_fetch_local_tasks` devolvía [] →
#          el mirror borraba todo y la pantalla Tareas quedó vacía sin
#          error. Mismas columnas (superset). Fallback al path legacy para
#          nodos 7.x. En 9.7 TaskFlow (UI/API) se retira pero el kernel de
#          run-history sigue escribiendo `task_runs` en el state DB.
#          + Sesiones nuevas desde SQLite: desde OpenClaw 2.0/9.4 las sesiones
#          viven en `agents/*/agent/openclaw-agent.sqlite` (`session_windows`)
#          y ya no hay .jsonl nuevos, así que el trigger del refresco
#          declarativo por sesión nueva no se disparaba NUNCA (identidad y
#          zonas de "Especializa tu agente" no llegaban al agente hasta un
#          reinicio). `SessionWindowsWatcher` detecta filas nuevas (solo
#          lectura, cada 5 s, sin cron) y dispara el mismo refresco.
# 1.50.0 — cron.add/cron.edit pasan `params.tz` como `--tz <iana>` junto a
#          `--cron`/`--at` (no con `--every`, el CLI lo rechaza). Recurrencias
#          "A una hora" disparan a la hora local del dueño (tnode_server#6).
__VERSION__ = "1.50.0"

